UPDATE device_shadow_projection
   SET shadow_version = #{shadow.shadowVersion},
       reported_state = CAST(#{shadow.stateJson} AS jsonb),
       reported_at = #{shadow.reportedAt}, received_at = #{shadow.receivedAt},
       applied_desired_version = #{shadow.appliedDesiredVersion},
       projection_version = #{shadow.projectionVersion}
 WHERE device_id = #{shadow.deviceId}
   AND projection_version = #{expectedProjectionVersion}
